<?php if ( ! defined( 'ABSPATH' ) ) { exit; } if($o['search_dropdown']!=='1') return; $terms=array_filter(array_map('trim',explode(',',$o['popular_searches']))); ?>
<div class="seh-panel seh-search-panel" hidden style="background:<?php echo esc_attr($o['search_bg']); ?>"><form role="search" method="get" action="<?php echo esc_url(home_url('/')); ?>"><input name="s" type="search" placeholder="<?php echo esc_attr($o['search_placeholder']); ?>" style="border-color:<?php echo esc_attr($o['search_border']); ?>"><input type="hidden" name="post_type" value="<?php echo class_exists('WooCommerce')?'product':'post'; ?>"><button style="background:<?php echo esc_attr($o['search_button']); ?>"><?php esc_html_e('Search','simple-ecommerce-header'); ?></button></form><?php if($o['show_popular']==='1'&&$terms): ?><p><?php esc_html_e('Popular searches','simple-ecommerce-header'); ?></p><div class="seh-chips"><?php foreach($terms as $term): ?><a href="<?php echo esc_url(add_query_arg(array('s'=>$term,'post_type'=>class_exists('WooCommerce')?'product':'post'),home_url('/'))); ?>"><?php echo esc_html($term); ?></a><?php endforeach; ?></div><?php endif; ?></div>
